  1	import React, { useCallback, useEffect, useMemo, useRef } from "react";
  2	import { TLShapeId, useEditor } from "tldraw";
  3	import { getValidRelationTypesBetween } from "./relationCreation";
  4	
  5	type RelationTypeDropdownProps = {
  6	  sourceId: TLShapeId;
  7	  targetId: TLShapeId;
  8	  dropdownPos: { x: number; y: number };
  9	  onSelect: (relationId: string) => void;
 10	  onDismiss: () => void;
 11	};
 12	
 13	export const RelationTypeDropdown = ({
 14	  sourceId,
 15	  targetId,
 16	  dropdownPos,
 17	  onSelect,
 18	  onDismiss,
 19	}: RelationTypeDropdownProps) => {
 20	  const editor = useEditor();
 21	  const dropdownRef = useRef<HTMLDivElement>(null);
 22	
 23	  const validRelationTypes = useMemo(
 24	    () => getValidRelationTypesBetween(editor, sourceId, targetId),
 25	    [editor, sourceId, targetId],
 26	  );
 27	
 28	  // Handle click outside
 29	  useEffect(() => {
 30	    const handlePointerDown = (e: PointerEvent) => {
 31	      if (
 32	        dropdownRef.current &&
 33	        !dropdownRef.current.contains(e.target as Node)
 34	      ) {
 35	        onDismiss();
 36	      }
 37	    };
 38	
 39	    const timer = setTimeout(() => {
 40	      window.addEventListener("pointerdown", handlePointerDown, true);
 41	    }, 100);
 42	
 43	    return () => {
 44	      clearTimeout(timer);
 45	      window.removeEventListener("pointerdown", handlePointerDown, true);
 46	    };
 47	  }, [onDismiss]);
 48	
 49	  // Handle Escape key
 50	  useEffect(() => {
 51	    const handleKeyDown = (e: KeyboardEvent) => {
 52	      if (e.key === "Escape") {
 53	        onDismiss();
 54	      }
 55	    };
 56	    window.addEventListener("keydown", handleKeyDown, true);
 57	    return () => window.removeEventListener("keydown", handleKeyDown, true);
 58	  }, [onDismiss]);
 59	
 60	  const handleSelect = useCallback(
 61	    (relationId: string) => {
 62	      onSelect(relationId);
 63	    },
 64	    [onSelect],
 65	  );
 66	
 67	  if (validRelationTypes.length === 0) return null;
 68	
 69	  return (
 70	    <div
 71	      ref={dropdownRef}
 72	      style={{
 73	        position: "absolute",
 74	        left: `${dropdownPos.x}px`,
 75	        top: `${dropdownPos.y}px`,
 76	        transform: "translate(-50%, -50%)",
 77	        pointerEvents: "all",
 78	        zIndex: 30,
 79	      }}
 80	      onPointerDown={(e) => e.stopPropagation()}
 81	      onPointerUp={(e) => e.stopPropagation()}
 82	      onClick={(e) => e.stopPropagation()}
 83	    >
 84	      <div className="max-h-[240px] min-w-[160px] overflow-y-auto rounded-lg border border-gray-200 bg-white p-4 shadow-lg">
 85	        <div className="px-2 py-1 text-xs font-semibold uppercase tracking-wide text-gray-500">
 86	          Relation Type
 87	        </div>
 88	        {validRelationTypes.map((rt) => (
 89	          <button
 90	            key={rt.id}
 91	            onClick={() => handleSelect(rt.id)}
 92	            className="flex w-full cursor-pointer items-center gap-2 rounded-md border-none bg-transparent px-3 py-2 text-left text-[13px] text-[#333] hover:bg-[#f0f0f0]"
 93	            onMouseEnter={(e) => {
 94	              (e.currentTarget as HTMLElement).style.backgroundColor =
 95	                "#f0f0f0";
 96	            }}
 97	            onMouseLeave={(e) => {
 98	              (e.currentTarget as HTMLElement).style.backgroundColor =
 99	                "transparent";
100	            }}
101	          >
102	            <span
103	              style={{
104	                backgroundColor: rt.color,
105	              }}
106	              className="h-2 w-2 flex-shrink-0 rounded-full bg-[#333]"
107	            />
108	            {rt.label}
109	          </button>
110	        ))}
111	      </div>
112	    </div>
113	  );
114	};

  1	import React, { useCallback, useEffect, useRef, useState } from "react";
  2	import { TLShapeId, useEditor, useValue } from "tldraw";
  3	import {
  4	  DiscourseNodeShape,
  5	  getDiscourseNodeTypeId,
  6	} from "~/components/canvas/DiscourseNodeUtil";
  7	import {
  8	  hasValidRelationTypes,
  9	  isDiscourseNodeShape,
 10	} from "~/components/canvas/canvasUtils";
 11	import { dispatchToastEvent } from "~/components/canvas/ToastListener";
 12	import { RelationTypeDropdown } from "./RelationTypeDropdown";
 13	import { createDefaultRelationBetweenNodes } from "./relationCreation";
 14	
 15	const HANDLE_RADIUS = 5;
 16	const HANDLE_HIT_AREA = 12;
 17	const HANDLE_PADDING = 8;
 18	
 19	type HandlePosition = {
 20	  x: number;
 21	  y: number;
 22	  anchor: { x: number; y: number };
 23	  direction: { x: number; y: number };
 24	};
 25	
 26	/** Pending connection: source + target nodes identified, waiting for relation type pick */
 27	type PendingConnection = {
 28	  sourceId: TLShapeId;
 29	  targetId: TLShapeId;
 30	  /** Viewport coords for dropdown positioning (midpoint between nodes) */
 31	  dropdownPos: { x: number; y: number };
 32	};
 33	
 34	const getEdgeMidpoints = (bounds: {
 35	  minX: number;
 36	  minY: number;
 37	  maxX: number;
 38	  maxY: number;
 39	}): HandlePosition[] => [
 40	  {
 41	    x: (bounds.minX + bounds.maxX) / 2,
 42	    y: bounds.minY,
 43	    anchor: { x: 0.5, y: 0 },
 44	    direction: { x: 0, y: -1 },
 45	  },
 46	  {
 47	    x: bounds.maxX,
 48	    y: (bounds.minY + bounds.maxY) / 2,
 49	    anchor: { x: 1, y: 0.5 },
 50	    direction: { x: 1, y: 0 },
 51	  },
 52	  {
 53	    x: (bounds.minX + bounds.maxX) / 2,
 54	    y: bounds.maxY,
 55	    anchor: { x: 0.5, y: 1 },
 56	    direction: { x: 0, y: 1 },
 57	  },
 58	  {
 59	    x: bounds.minX,
 60	    y: (bounds.minY + bounds.maxY) / 2,
 61	    anchor: { x: 0, y: 0.5 },
 62	    direction: { x: -1, y: 0 },
 63	  },
 64	];
 65	
 66	export const DragHandleOverlay = () => {
 67	  const editor = useEditor();
 68	
 69	  // Drag state: track the drag line in viewport coords (no tldraw shapes)
 70	  const [isDragging, setIsDragging] = useState(false);
 71	  const [dragStart, setDragStart] = useState<{ x: number; y: number } | null>(
 72	    null,
 73	  );
 74	  const [dragEnd, setDragEnd] = useState<{ x: number; y: number } | null>(null);
 75	  const [hoveredTarget, setHoveredTarget] = useState<TLShapeId | null>(null);
 76	
 77	  // After a successful drop, show the relation type dropdown
 78	  const [pending, setPending] = useState<PendingConnection | null>(null);
 79	
 80	  const sourceNodeRef = useRef<DiscourseNodeShape | null>(null);
 81	  const dragCleanupRef = useRef<(() => void) | null>(null);
 82	
 83	  useEffect(() => {
 84	    return () => {
 85	      dragCleanupRef.current?.();
 86	    };
 87	  }, []);
 88	
 89	  // Track the single selected discourse node
 90	  const selectedNode = useValue<DiscourseNodeShape | null>(
 91	    "dragHandleSelectedNode",
 92	    () => {
 93	      if (isDragging || pending) return sourceNodeRef.current;
 94	      const shape = editor.getOnlySelectedShape();
 95	      if (shape && isDiscourseNodeShape(editor, shape)) {
 96	        return shape;
 97	      }
 98	      return null;
 99	    },
100	    [editor, isDragging, pending],
101	  );
102	
103	  // Compute handle positions in viewport space
104	  const handlePositions = useValue<
105	    { left: number; top: number; anchor: { x: number; y: number } }[] | null
106	  >(
107	    "dragHandlePositions",
108	    () => {
109	      if (!selectedNode || pending || isDragging) return null;
110	      const bounds = editor.getShapePageBounds(selectedNode.id);
111	      if (!bounds) return null;
112	      const midpoints = getEdgeMidpoints(bounds);
113	      return midpoints.map((mp) => {
114	        const vp = editor.pageToViewport({ x: mp.x, y: mp.y });
115	        return {
116	          left: vp.x + mp.direction.x * HANDLE_PADDING,
117	          top: vp.y + mp.direction.y * HANDLE_PADDING,
118	          anchor: mp.anchor,
119	        };
120	      });
121	    },
122	    [editor, selectedNode?.id, pending, isDragging],
123	  );
124	
125	  const handlePointerDown = useCallback(
126	    (e: React.PointerEvent) => {
127	      if (!selectedNode) return;
128	      e.preventDefault();
129	      e.stopPropagation();
130	      e.nativeEvent.stopImmediatePropagation();
131	
132	      sourceNodeRef.current = selectedNode;
133	      setIsDragging(true);
134	
135	      const startVp = { x: e.clientX, y: e.clientY };
136	      // Get container bounding rect to convert client coords to overlay-relative
137	      const containerRect = editor.getContainer().getBoundingClientRect();
138	      setDragStart({
139	        x: startVp.x - containerRect.left,
140	        y: startVp.y - containerRect.top,
141	      });
142	      setDragEnd({
143	        x: startVp.x - containerRect.left,
144	        y: startVp.y - containerRect.top,
145	      });
146	
147	      const containerEl = editor.getContainer();
148	
149	      const onPointerMove = (moveEvent: PointerEvent) => {
150	        const rect = containerEl.getBoundingClientRect();
151	        setDragEnd({
152	          x: moveEvent.clientX - rect.left,
153	          y: moveEvent.clientY - rect.top,
154	        });
155	
156	        // Check for target node under cursor
157	        const pagePoint = editor.screenToPage({
158	          x: moveEvent.clientX,
159	          y: moveEvent.clientY,
160	        });
161	        const target = editor.getShapeAtPoint(pagePoint, {
162	          hitInside: true,
163	          hitFrameInside: true,
164	          margin: 0,
165	          filter: (s) =>
166	            isDiscourseNodeShape(editor, s) &&
167	            s.id !== selectedNode.id &&
168	            !s.isLocked,
169	        });
170	        setHoveredTarget(target?.id ?? null);
171	        editor.setHintingShapes(target ? [target.id] : []);
172	      };
173	
174	      const onPointerUp = (upEvent: PointerEvent) => {
175	        containerEl.removeEventListener("pointermove", onPointerMove);
176	        containerEl.removeEventListener("pointerup", onPointerUp);
177	        dragCleanupRef.current = null;
178	        editor.setHintingShapes([]);
179	        setIsDragging(false);
180	        setDragStart(null);
181	        setDragEnd(null);
182	        setHoveredTarget(null);
183	
184	        // Check what we dropped on
185	        const pagePoint = editor.screenToPage({
186	          x: upEvent.clientX,
187	          y: upEvent.clientY,
188	        });
189	        const target = editor.getShapeAtPoint(pagePoint, {
190	          hitInside: true,
191	          hitFrameInside: true,
192	          margin: 0,
193	          filter: (s) =>
194	            isDiscourseNodeShape(editor, s) &&
195	            s.id !== selectedNode.id &&
196	            !s.isLocked,
197	        });
198	
199	        if (!target) {
200	          dispatchToastEvent({
201	            id: "tldraw-drag-handle-warning",
202	            title: "Drop on a discourse node to create a relation",
203	            severity: "warning",
204	          });
205	          sourceNodeRef.current = null;
206	          return;
207	        }
208	
209	        // Validate that relation types exist between these node types
210	        const selectedNodeTypeId = getDiscourseNodeTypeId({
211	          shape: selectedNode,
212	        });
213	        const targetNodeTypeId = getDiscourseNodeTypeId({ shape: target });
214	        if (!hasValidRelationTypes(selectedNodeTypeId, targetNodeTypeId)) {
215	          dispatchToastEvent({
216	            id: "tldraw-no-valid-relation",
217	            title: "No relation types are defined between these node types",
218	            severity: "warning",
219	          });
220	          sourceNodeRef.current = null;
221	          return;
222	        }
223	
224	        // Compute dropdown position: midpoint between source and target in viewport space
225	        const sourceBounds = editor.getShapePageBounds(selectedNode.id);
226	        const targetBounds = editor.getShapePageBounds(target.id);
227	        if (!sourceBounds || !targetBounds) {
228	          sourceNodeRef.current = null;
229	          return;
230	        }
231	        const midPage = {
232	          x: (sourceBounds.midX + targetBounds.midX) / 2,
233	          y: (sourceBounds.midY + targetBounds.midY) / 2,
234	        };
235	        const midVp = editor.pageToViewport(midPage);
236	
237	        setPending({
238	          sourceId: selectedNode.id,
239	          targetId: target.id,
240	          dropdownPos: midVp,
241	        });
242	      };
243	
244	      containerEl.addEventListener("pointermove", onPointerMove);
245	      containerEl.addEventListener("pointerup", onPointerUp);
246	      dragCleanupRef.current = () => {
247	        containerEl.removeEventListener("pointermove", onPointerMove);
248	        containerEl.removeEventListener("pointerup", onPointerUp);
249	        dragCleanupRef.current = null;
250	      };
251	    },
252	    [selectedNode, editor],
253	  );
254	
255	  const handleDropdownSelect = useCallback(
256	    (relationId: string) => {
257	      if (!pending) return;
258	
259	      void createDefaultRelationBetweenNodes({
260	        editor,
261	        relationId,
262	        sourceId: pending.sourceId,
263	        targetId: pending.targetId,
264	      });
265	
266	      setPending(null);
267	      sourceNodeRef.current = null;
268	    },
269	    [editor, pending],
270	  );
271	
272	  const handleDropdownDismiss = useCallback(() => {
273	    setPending(null);
274	    if (sourceNodeRef.current) {
275	      editor.select(sourceNodeRef.current.id);
276	    }
277	    sourceNodeRef.current = null;
278	  }, [editor]);
279	
280	  const showHandles = !!handlePositions && !pending && !isDragging;
281	
282	  return (
283	    <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
284	      {/* Drag handle dots */}
285	      {showHandles &&
286	        handlePositions.map((pos, i) => (
287	          <div
288	            key={i}
289	            className="absolute z-20 flex cursor-crosshair items-center justify-center"
290	            onPointerDown={handlePointerDown}
291	            style={{
292	              left: `${pos.left}px`,
293	              top: `${pos.top}px`,
294	              width: `${HANDLE_HIT_AREA * 2}px`,
295	              height: `${HANDLE_HIT_AREA * 2}px`,
296	              transform: "translate(-50%, -50%)",
297	              pointerEvents: "all",
298	            }}
299	          >
300	            <div
301	              style={{
302	                width: `${HANDLE_RADIUS * 2}px`,
303	                height: `${HANDLE_RADIUS * 2}px`,
304	                borderRadius: "50%",
305	                backgroundColor: "#adb5bd",
306	              }}
307	            />
308	          </div>
309	        ))}
310	
311	      {/* SVG drag line while dragging */}
312	      {isDragging && dragStart && dragEnd && (
313	        <svg
314	          style={{
315	            position: "absolute",
316	            inset: 0,
317	            width: "100%",
318	            height: "100%",
319	            pointerEvents: "none",
320	            zIndex: 19,
321	          }}
322	        >
323	          <line
324	            x1={dragStart.x}
325	            y1={dragStart.y}
326	            x2={dragEnd.x}
327	            y2={dragEnd.y}
328	            stroke={hoveredTarget ? "#339af0" : "#adb5bd"}
329	            strokeWidth={2}
330	            strokeDasharray={hoveredTarget ? "none" : "6 4"}
331	          />
332	          {/* Arrowhead */}
333	          <circle
334	            cx={dragEnd.x}
335	            cy={dragEnd.y}
336	            r={4}
337	            fill={hoveredTarget ? "#339af0" : "#adb5bd"}
338	          />
339	        </svg>
340	      )}
341	
342	      {/* Relation type dropdown */}
343	      {pending && (
344	        <RelationTypeDropdown
345	          sourceId={pending.sourceId}
346	          targetId={pending.targetId}
347	          dropdownPos={pending.dropdownPos}
348	          onSelect={handleDropdownSelect}
349	          onDismiss={handleDropdownDismiss}
350	        />
351	      )}
352	    </div>
353	  );
354	};

You are working on the Roam Research extension that implements the Discourse Graph protocol.

## Dependencies

Prefer existing dependencies from package.json.

## Roam Style Guide

Platform-native UI - use BlueprintJS 3 components and Tailwind CSS.
Use `text-red-700` for error message text so errors have a consistent visual treatment. Keep danger buttons, borders, backgrounds, and diagram colors separate from this text convention. Obsidian keeps `text-error`; website and shared UI keep `text-destructive`.
Do not introduce arbitrary visual styling, new shading colors, background palettes, gradients, accent colors, border colors, or text colors unless the user explicitly asks for them.
When styling Roam UI, use this priority order:

1. Use basic BlueprintJS patterns and components first.
2. Reuse existing repo examples and established Tailwind styling patterns before adding anything new.
3. Fall back to Roam-native styling and colors.

Any new Roam UI should feel native to Roam and consistent with existing BlueprintJS and repository usage, not like a separate visual palette.
Use the roamAlphaApi docs from https://roamresearch.com/#/app/developer-documentation/page/tIaOPdXCj.
Use Roam Depot/Extension API docs from https://roamresearch.com/#/app/developer-documentation/page/y31lhjIqU.
