export const createAllRelationShapeUtils = (
  allRelationIds: string[],
): TLShapeUtilConstructor<DiscourseRelationShape>[] => {
  const relationShapeUtils = allRelationIds.map((id) => {
    class DiscourseRelationUtil extends BaseDiscourseRelationUtil {
      static override type = id;

      handleCreateRelationsInRoam = async ({
        arrow,
        targetId,
      }: {
        arrow: DiscourseRelationShape;
        targetId: TLShapeId;
      }) => {
        const editor = this.editor;
        const deleteAndWarn = (content: string) => {
          dispatchToastEvent({
            id: `tldraw-cancel-and-warn-${content}`,
            title: content,
            severity: "warning",
          });
          this.editor.deleteShapes([arrow.id]);
        };
        const target = editor.getShape(targetId);
        const bindings = editor.getBindingsFromShape(arrow, arrow.type);
        const sourceId = bindings.find((b) => b.toId !== targetId)?.toId;
        if (!sourceId) return;
        const source = editor.getShape(sourceId);
        if (!target || !source) return;
        if (
          !isDiscourseNodeShapeTypeGuard(target) ||
          !isDiscourseNodeShapeTypeGuard(source)
        ) {
          return deleteAndWarn(
            "Invalid shape type. Expected a DiscourseNodeShape.",
          );
        }
        const relations = Object.values(discourseContext.relations).flat();
        const relation = relations.find((r) => r.id === arrow.type);
        if (!relation) return;

        const sourceNodeType = getDiscourseNodeTypeId({ shape: source });
        const targetNodeType = getDiscourseNodeTypeId({ shape: target });

        // Check all relations with the same label for a match
        const {
          isDirect,
          isReverse,
          matchingRelation: foundRelation,
        } = this.checkConnectionTypeAcrossLabel(
          relation.label,
          sourceNodeType,
          targetNodeType,
        );
        const matchingRelation = foundRelation ?? relation;

        if (!isDirect && !isReverse) {
          const validTargets = this.getValidTargetTypes(
            relation.label,
            sourceNodeType,
          );
          const uniqueTargetTexts = validTargets.map(
            (t) => discourseContext.nodes[t]?.text || t,
          );
          return deleteAndWarn(
            `Target node must be of type ${uniqueTargetTexts.join(", ")}`,
          );
        }

        // If we found a matching relation with a different ID, switch to it
        if (matchingRelation.id !== arrow.type) {
          // Get bindings before updating the shape type
          const existingBindings = editor.getBindingsFromShape(
            arrow,
            arrow.type,
          );
          // Update the shape type
          editor.updateShapes([{ id: arrow.id, type: matchingRelation.id }]);
          // Update bindings to use the new relation type
          for (const binding of existingBindings) {
            editor.updateBinding({
              ...binding,
              type: matchingRelation.id,
            });
          }
        }
        if (getStoredRelationsEnabled()) {
          const sourceAsDNS = asDiscourseNodeShape(source, editor);
          const targetAsDNS = asDiscourseNodeShape(target, editor);

          if (sourceAsDNS && targetAsDNS) {
            const isOriginal = isDirect;
            await createReifiedRelation({
              sourceUid: isOriginal
                ? sourceAsDNS.props.uid
                : targetAsDNS.props.uid,
              destinationUid: isOriginal
                ? targetAsDNS.props.uid
                : sourceAsDNS.props.uid,
              relationBlockUid: matchingRelation.id,
            });
          } else {
            void internalError({
              error: "attempt to create a relation between non discourse nodes",
              type: "Canvas create relation",
            });
          }
        } else {
          const { triples } = matchingRelation;
          const isOriginal = isDirect;

          const newTriples = triples
            .map((t) => {
              if (/is a/i.test(t[1])) {
                const targetNode =
                  (t[2] === "source" && isOriginal) ||
                  (t[2] === "destination" && !isOriginal)
                    ? source
                    : target;
                const { title, uid } =
                  targetNode.props as DiscourseNodeShape["props"];
                return [
                  t[0],
                  isPageUid(uid) ? "has title" : "with uid",
                  isPageUid(uid) ? title : uid,
                ];
              }
              return t.slice(0);
            })
            .map(([source, relation, target]) => ({
              source,
              relation,
              target,
            }));
          // Get canvas page UID from the DOM (supports multiple canvases)
          const canvasPageUid = getCanvasPageUidFromDOM();
          if (!canvasPageUid) {
            return deleteAndWarn("No canvas page UID found");
          }
          const title = getPageTitleByPageUid(canvasPageUid);
          await triplesToBlocks({
            defaultPageTitle: `Auto generated from [[${title}]]`,
            toPage: async (title: string, blocks: InputTextNode[]) => {
              const parentUid =
                getPageUidByPageTitle(title) ||
                (await createPage({ title: title }));

              await Promise.all(
                blocks.map((node, order) =>
                  createBlock({ node, order, parentUid }).catch(() =>
                    console.error(
                      `Failed to create block: ${JSON.stringify(
                        { node, order, parentUid },
                        null,
                        4,
                      )}`,
                    ),
                  ),
                ),
              );
              await openBlockInSidebar(parentUid);
            },
            nodeSpecificationsByLabel: Object.fromEntries(
              Object.values(discourseContext.nodes).map((n) => [
                n.text,
                n.specification,
              ]),
            ),
          })(newTriples)();
        }
        refreshDiscourseContextsForMutatedUids({
          uids: [source.props.uid, target.props.uid],
        });
      };

      override getDefaultProps(): DiscourseRelationShape["props"] {
        // TODO: get color from canvasSettings

        const relations = Object.values(discourseContext.relations);
        // TODO - add canvas settings to relations config
        const relationIndex = relations.findIndex((rs) =>
          rs.some((r) => r.id === id),
        );
        const isValid = relationIndex >= 0 && relationIndex < relations.length;
        const color = isValid ? COLOR_ARRAY[relationIndex + 1] : COLOR_ARRAY[0];
        const text = isValid ? relations[relationIndex][0].label : "";

        return {
          dash: "draw",
          size: "m",
          fill: "none",
          color: color,
          labelColor: color,
          bend: 0,
          start: { x: 0, y: 0 },
          end: { x: 0, y: 0 },
          arrowheadStart: "none",
          arrowheadEnd: "arrow",
          text: text,
          labelPosition: 0.5,
          font: "draw",
          scale: 1,
          relationTypeId: null,
        };
      }
      override onHandleDrag: TLOnHandleDragHandler<DiscourseRelationShape> = (
        shape,
        { handle, isPrecise },
      ) => {
        const handleId = handle.id as ARROW_HANDLES;
        const bindings = getArrowBindings(this.editor, shape);

        if (handleId === ARROW_HANDLES.MIDDLE) {
          // Bending the arrow...
---
              terminalBinding.binding.props.terminal,
            );
          }
        }
      };
    }
    return DiscourseRelationUtil;
  });

  class DiscourseRelationFallbackUtil extends BaseDiscourseRelationUtil {
    static override type = DISCOURSE_RELATION_SHAPE_TYPE;

    handleCreateRelationsInRoam = (): Promise<void> => Promise.resolve();
  }

  return [...relationShapeUtils, DiscourseRelationFallbackUtil];
};

