export const createDiscourseNodeType = async ({
  label,
  shortcut,
  format,
  template,
  uid,
}: {
  label: string;
  shortcut?: string;
  format?: string;
  template?: RoamBasicNode[] | string; // string would be markdown
  uid?: string;
}): Promise<DiscourseNode> => {
  if (shortcut === undefined) shortcut = getUnusedShortcut(label);
  format = format ?? `[[${label.slice(0, 3).toUpperCase()}]] - {content}`;
  const tree = [
    {
      text: "Shortcut",
      children: [{ text: shortcut }],
    },
    {
      text: "Tag",
      children: [{ text: "" }],
    },
    {
      text: "Format",
      children: [{ text: format }],
    },
  ];
  let templateTree: RoamBasicNode[] | undefined;
  if (template !== undefined) {
    templateTree = Array.isArray(template) ? template : [];
    tree.push({
      text: "Template",
      children: templateTree,
    });
  }
  const pageUid = await createPage({
    title: `${DISCOURSE_NODE_PAGE_PREFIX}${label}`,
    uid,
    tree,
  });
  if (typeof template === "string") {
    const tree = getBasicTreeByParentUid(pageUid);
    const templateUid = getSubTree({ tree, key: "Template" }).uid;
    await getRoamMarkdownApi().block.fromMarkdown({
      location: { "parent-uid": templateUid, order: "last" },
      "markdown-string": template,
    });
    templateTree = getBasicTreeByParentUid(templateUid);
  }
  const settings = DiscourseNodeSchema.parse({
    text: label,
    type: pageUid,
    shortcut,
    format,
    template: templateTree,
  });
  setBlockProps(pageUid, settings);
  await setBlockPropsAsync(pageUid, settings);
  invalidateDiscourseNodeTypeCaches();
  return toDiscourseNode(settings);
};

/**
 * Migrate known legacy block prop shapes to the current schema.
 *
 * - specification: Condition[] → {enabled, query: {conditions, ...}}
 * - specification: {enabled, query: Condition[]} → {enabled, query: {conditions, ...}}
 * - suggestiveRules.isFirstChild: {uid, value} → boolean
 */
const migrateNodeBlockProps = (
  props: Record<string, json>,
): Record<string, json> => {
  const migrated = { ...props };

  if (Array.isArray(migrated.specification)) {
    migrated.specification = {
      enabled: migrated.specification.length > 0,
      query: {
        conditions: migrated.specification,
        selections: [],
        custom: "",
        returnNode: "node",
      },
    };
  } else if (
    typeof migrated.specification === "object" &&
    migrated.specification !== null &&
    "query" in migrated.specification &&
    Array.isArray((migrated.specification as Record<string, json>).query)
  ) {
    const spec = migrated.specification as Record<string, json>;
    migrated.specification = {
      enabled:
        typeof spec.enabled === "boolean"
          ? spec.enabled
          : (spec.query as json[]).length > 0,
      query: {
        conditions: spec.query,
        selections: [],
        custom: "",
        returnNode: "node",
      },
    };
  }

  if (
    typeof migrated.suggestiveRules === "object" &&
    migrated.suggestiveRules !== null &&
    !Array.isArray(migrated.suggestiveRules)
  ) {
    const rules = migrated.suggestiveRules as Record<string, json>;
    const ifc = rules.isFirstChild;
    if (typeof ifc === "object" && ifc !== null && !Array.isArray(ifc)) {
      migrated.suggestiveRules = {
        ...rules,
        isFirstChild: (ifc as Record<string, json>).value ?? false,
      };
    }
  }

  return migrated;
};

