const useCloudflareCanvasStore = ({
  pageUid,
  migrations,
  customShapeUtils,
  customBindingUtils,
  customShapeTypes,
  customBindingTypes,
}: CanvasStoreAdapterArgs): CanvasStoreAdapterResult => {
  const { store, error, isLoading } = useCloudflareSyncStore({
    pageUid,
    migrations,
    customShapeUtils,
    customBindingUtils,
    customShapeTypes,
    customBindingTypes,
  });
  return {
    store,
    error,
    isLoading,
    needsUpgrade: false,
    performUpgrade: () => {},
    const isInvalidRecord = /invalidRecord/i.test(error.message);
    console.error("[DG Canvas] Store error", {
      title,
      pageUid,
      message: error.message,
      stack: error.stack,
      ...(isInvalidRecord
        ? {
            hint: "Cloudflare sync worker schema is rejecting one or more custom records.",
            customShapeTypes,
            customBindingTypes,
          }
        : {}),
    });
    internalError({
      error,
      type: "Canvas Store Error",
      context: {
        title,
        pageUid,
        ...(isInvalidRecord
          ? {
              customShapeTypes,
              customBindingTypes,
            }
          : {}),
      },
    });
  }, [error, pageUid, title, customShapeTypes, customBindingTypes]);

  const isCanvasBlocked =
    if (parentEl.querySelector(".roamjs-tldraw-canvas-container"))
      return () => {};

    parentEl.appendChild(canvasWrapperEl);
    canvasWrapperEl.style.minHeight = minHeight;
    canvasWrapperEl.style.height = height;
  }

  const unmount = renderWithUnmount(
    <ExtensionApiContextProvider {...onloadArgs}>
      <TldrawCanvas title={title} />
    </ExtensionApiContextProvider>,
    canvasWrapperEl,
  );

  const originalUnmount = unmount;
  return () => {
    originalUnmount();
    canvasWrapperEl.remove();
  };
};

